import sys
import math

def find_release_point(b, tx, ty):
    def spiral_point(phi):
        r = b * phi
        return r * math.cos(phi), r * math.sin(phi)

    def intersects_spiral(phi1, phi2):
        x1, y1 = spiral_point(phi1)
        x2, y2 = spiral_point(phi2)
        dx = x2 - x1
        dy = y2 - y1
        for phi in [phi1, phi2]:
            r = b * phi
            cx, cy = r * math.cos(phi), r * math.sin(phi)
            if (cx - tx) * dy == (cy - ty) * dx:
                return True
        return False

    low, high = 0, 10000
    while high - low > 1e-7:
        mid = (low + high) / 2
        x, y = spiral_point(mid)
        vx, vy = -b * mid * math.sin(mid), b * mid * math.cos(mid)
        dx, dy = tx - x, ty - y
        if vx * dx + vy * dy > 0 and not intersects_spiral(low, mid):
            high = mid
        else:
            low = mid
    return spiral_point(low)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    b = float(data[0])
